import React, { useEffect, useMemo, useRef, useState } from "react";
import FloatingUploadButton from "./FloatingUploadButton";

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value));
}

const formatTime = (value) => {
  const total = Math.max(0, Number(value) || 0);
  const minutes = Math.floor(total / 60);
  const seconds = Math.floor(total % 60);
  const tenths = Math.floor((total - Math.floor(total)) * 10);
  return `${String(minutes).padStart(2, "0")}:${String(seconds).padStart(2, "0")}.${tenths}`;
};

export default function TimelineScroller({ duration, currentTime, onSeek, onUploadClick, loading }) {
  const outerRef = useRef(null);
  const innerRef = useRef(null);
  const [isScrubbing, setIsScrubbing] = useState(false);
  const [hoverTime, setHoverTime] = useState(null);

  const markerCount = useMemo(() => {
    if (!duration) return 0;
    return Math.min(12, Math.max(3, Math.floor(duration / 2)));
  }, [duration]);

  const markers = useMemo(() => {
    if (!duration || markerCount === 0) return [];
    const step = duration / markerCount;
    return Array.from({ length: markerCount + 1 }, (_, index) => Math.min(duration, index * step));
  }, [duration, markerCount]);

  const computeTimeFromPointer = (clientX) => {
    const outer = outerRef.current;
    const inner = innerRef.current;
    if (!outer || !inner || !duration) return 0;
    const rect = outer.getBoundingClientRect();
    const x = clientX - rect.left + outer.scrollLeft;
    const pct = clamp(x / Math.max(inner.scrollWidth, 1), 0, 1);
    return pct * duration;
  };

  const seekFromPointer = (clientX) => {
    const time = computeTimeFromPointer(clientX);
    onSeek?.(time);
  };

  const handlePointerDown = (event) => {
    if (!duration) return;
    setIsScrubbing(true);
    outerRef.current?.setPointerCapture?.(event.pointerId);
    seekFromPointer(event.clientX);
  };

  const handlePointerMove = (event) => {
    if (!duration) return;
    const time = computeTimeFromPointer(event.clientX);
    setHoverTime(time);
    if (isScrubbing) seekFromPointer(event.clientX);
  };

  const handlePointerUp = () => {
    setIsScrubbing(false);
  };

  useEffect(() => {
    const handleGlobalPointerUp = () => setIsScrubbing(false);
    document.addEventListener("pointerup", handleGlobalPointerUp);
    return () => document.removeEventListener("pointerup", handleGlobalPointerUp);
  }, []);

  useEffect(() => {
    const outer = outerRef.current;
    const inner = innerRef.current;
    if (!outer || !inner || !duration) return;

    const targetLeft = clamp((currentTime / duration) * inner.scrollWidth - outer.clientWidth / 2, 0, Math.max(0, inner.scrollWidth - outer.clientWidth));
    if (!isScrubbing) {
      outer.scrollTo({ left: targetLeft, behavior: "smooth" });
    }
  }, [currentTime, duration, isScrubbing]);

  const activeLabel = hoverTime != null ? formatTime(hoverTime) : formatTime(currentTime);

  return (
    <div className="relative min-h-0 flex h-full flex-col overflow-hidden rounded-[28px] bg-slate-950/90 shadow-soft">
      <div className="flex items-center justify-between px-4 pt-4">
        <div className="text-xs uppercase tracking-[0.35em] text-slate-400">Timeline</div>
        <div className="rounded-full bg-slate-900/80 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.2em] text-slate-200 ring-1 ring-white/10">
          {isScrubbing ? "Scrubbing..." : activeLabel}
        </div>
      </div>

      <div className="relative flex-1 px-4 pb-4 pt-3">
        <div
          ref={outerRef}
          className="relative h-full overflow-x-auto overflow-y-hidden rounded-[24px] bg-slate-900/80 px-6 py-4 touch-pan-x scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-slate-950"
          onPointerDown={handlePointerDown}
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerCancel={handlePointerUp}
          style={{ touchAction: "pan-x" }}
        >
          <div ref={innerRef} className="relative h-full w-full">
            <div className="absolute inset-0 rounded-[20px] border border-white/10 bg-slate-950/70" />
            <div className="absolute left-4 right-4 top-1/2 h-1 rounded-full bg-slate-800" />
            <div
              className="absolute left-4 top-1/2 h-1 rounded-full bg-rose-500"
              style={{ width: `${duration ? (currentTime / duration) * 100 : 0}%` }}
            />
            <div className="absolute inset-0 flex flex-col items-center justify-center px-6 text-center">
              <div className="text-sm font-semibold text-slate-200">
                {loading
                  ? "Preparing timeline..."
                  : duration
                  ? "Drag across the scrub track to seek frames"
                  : "Upload a video to begin tamper detection"}
              </div>
              <div className="mt-2 text-xs text-slate-400">
                The upload button is the black floating control in the bottom-left.
              </div>
            </div>

            <div className="pointer-events-none absolute inset-x-0 top-0 px-10 pt-3 text-[11px] text-slate-500">
              {markers.map((marker, index) => {
                const left = duration ? (marker / duration) * 100 : 0;
                return (
                  <div
                    key={`${marker}-${index}`}
                    className="absolute -translate-x-1/2 text-center"
                    style={{ left: `${left}%` }}
                  >
                    <div className="mb-1 h-2 w-2 rounded-full bg-slate-500/70" />
                    <div>{formatTime(marker)}</div>
                  </div>
                );
              })}
            </div>
          </div>

          <FloatingUploadButton onClick={onUploadClick} />
        </div>
      </div>
    </div>
  );
}
